func TestAuthenticationGRPCJWTWithoutDatabase(t *testing.T) {
	privateKey, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		t.Fatal(err)
	}
	keyPath := filepath.Join(t.TempDir(), "public.pem")
	publicKey, err := x509.MarshalPKIXPublicKey(&privateKey.PublicKey)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(keyPath, pem.EncodeToMemory(&pem.Block{Type: "PUBLIC KEY", Bytes: publicKey}), 0600); err != nil {
		t.Fatal(err)
	}

	cfg := &config.Config{}
	cfg.Storage.Type = config.LocalStorageType
	cfg.Database.URL = "invalid-database-url"
	cfg.Authentication.Required = true
	cfg.Authentication.Methods.JWT.Enabled = true
	cfg.Authentication.Methods.JWT.Method.PublicKeyFile = keyPath

	register, interceptors, shutdown, err := authenticationGRPC(context.Background(), zaptest.NewLogger(t), cfg, false, false)
	if err != nil {
		t.Fatal(err)
	}
	if len(register) != 2 {
		t.Errorf("got %d registerers, want 2", len(register))
	}
	if len(interceptors) == 0 {
		t.Error("JWT authentication middleware was not installed")
	}
	if err := shutdown(context.Background()); err != nil {
		t.Fatal(err)
	}
}
package config

import (
	"testing"
	"time"
)

func TestAuthenticationDatabaseRequirements(t *testing.T) {
	schedule := &AuthenticationCleanupSchedule{Interval: time.Hour, GracePeriod: time.Minute}
	cfg := AuthenticationConfig{}
	if cfg.RequiresDatabase() || cfg.ShouldRunCleanup() {
		t.Fatal("disabled authentication should not require a database or cleanup")
	}
	for _, method := range cfg.Methods.AllMethods() {
		if method.RequiresDatabase != (method.Name() != "jwt") {
			t.Errorf("%s: unexpected database requirement", method.Name())
		}
	}
	cfg.Methods.JWT.Enabled = true
	cfg.Methods.JWT.Cleanup = schedule
	if cfg.RequiresDatabase() || cfg.ShouldRunCleanup() {
		t.Fatal("JWT alone should not require a database or cleanup")
	}
	cfg.Methods.Token.Cleanup = schedule
	if cfg.RequiresDatabase() || cfg.ShouldRunCleanup() {
		t.Fatal("disabled token method should not require a database or cleanup")
	}
	cfg.Methods.Token.Enabled = true
	if !cfg.RequiresDatabase() || !cfg.ShouldRunCleanup() {
		t.Fatal("enabled token method with cleanup should require database and cleanup")
	}
}
